<label className="transaction-select"><select value={txCategoryFilter} onChange={e=>setTxCategoryFilter(e.target.value)} aria-label="ক্যাটাগরি ফিল্টার"><option>সব ক্যাটাগরি</option>{Array.from(new Set(tx.map(t=>t.category))).sort().map(item=><option key={item}>{item}</option>)}</select><ChevronDown size={13}/></label>
